/** Why an ownership-handover action was refused; see `OwnershipHandoverError`. */
export type OwnershipHandoverRefusal =
  | "self"
  | "pending_exists"
  | "nothing_pending"
  | "expired";

const OWNERSHIP_HANDOVER_MESSAGES: Readonly<
  Record<OwnershipHandoverRefusal, string>
> = {
  self: "The owner cannot offer the workspace to themselves.",
  pending_exists: "An ownership offer is already pending for this workspace.",
  nothing_pending: "There is no pending ownership offer to act on.",
  expired: "That ownership offer has expired.",
};

/** Thrown by the ownership-handover guards in `organization-service`. */
export class OwnershipHandoverError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly reason: OwnershipHandoverRefusal) {
    super(OWNERSHIP_HANDOVER_MESSAGES[reason]);
    this.name = "OwnershipHandoverError";
