/**
 * Ownership-handover offers. At most one row per org is ever `pending`; the
 * service layer enforces that, this layer just stores and transitions rows.
 *
 * Must call (do not reimplement): newId
 */
import { and, eq, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, ownershipHandovers } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toOwnershipHandover } from "./_mappers";
import type { OrgId, UserId } from "@/types/common";
import type { OwnershipHandover, OwnershipHandoverStatus } from "@/types/organization";

/** How long a fresh offer stays actionable before it lapses. */
const HANDOVER_TTL_MS = 7 * 24 * 60 * 60 * 1000;

export async function findPendingHandover(
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        eq(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .get();
  return row ? toOwnershipHandover(row) : null;
}

export async function insertHandover(
  orgId: OrgId,
  fromUserId: UserId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  const createdAt = toIsoTimestamp(new Date());
  const expiresAt = toIsoTimestamp(
    new Date(Date.parse(createdAt) + HANDOVER_TTL_MS),
  );

  const row = getDb()
    .insert(ownershipHandovers)
    .values({
      id: newId(),
      orgId,
      fromUserId,
      toUserId,
      status: "pending",
      expiresAt,
      createdAt,
      resolvedAt: null,
    })
    .returning()
    .get();

  return toOwnershipHandover(row);
}

/** Lazily flips a lapsed offer to `expired`; never touches `resolvedAt`. */
export async function markExpired(orgId: OrgId, id: string): Promise<void> {
  getDb()
    .update(ownershipHandovers)
    .set({ status: "expired" })
    .where(
      and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.id, id)),
    )
    .run();
}

export async function resolveHandover(
  orgId: OrgId,
  id: string,
  status: Extract<OwnershipHandoverStatus, "accepted" | "declined" | "canceled">,
): Promise<OwnershipHandover> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt: toIsoTimestamp(new Date()) })
    .where(
      and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.id, id)),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Ownership handover ${id} not found in org ${orgId}`);
  return toOwnershipHandover(row);
}

/**
 * Withdraws whatever offer `userId` is a party to, on either side. Called when
 * a member leaves the workspace so a dangling offer never outlives either
 * participant.
 */
export async function cancelOpenHandoverForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  getDb()
    .update(ownershipHandovers)
    .set({ status: "canceled", resolvedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        eq(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        or(
          eq(ownershipHandovers.fromUserId, userId),
          eq(ownershipHandovers.toUserId, userId),
        ),
      ),
    )
    .run();
}

