import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("./tests/server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("./tests/server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { OwnershipHandoverError } from "@/lib/errors";
import { PermissionDeniedError } from "@/lib/permissions";
import * as memberRepo from "@/server/repositories/member-repository";
import * as memberService from "@/server/services/member-service";
import * as orgService from "@/server/services/organization-service";
import { createTenant, useTemporaryDatabase } from "./tests/server/_support/fixtures";
import type { Tenant } from "./tests/server/_support/fixtures";

let cleanup: () => void;

describe("ownership handover scratch", () => {
  it("full happy path + guards", async () => {
    cleanup = await useTemporaryDatabase();
    const tenant: Tenant = await createTenant("handover-scratch", "growth");

    // non-recorded-owner (even with owner role) cannot initiate
    const adminMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: adminMember!.id,
      role: "owner",
    });
    await expect(
      orgService.initiateOwnershipHandover(
        { ...tenant.actors.admin, role: "owner" },
        tenant.org.id,
        tenant.userIds.member,
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    // self offer refused
    await expect(
      orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.owner),
    ).rejects.toMatchObject({ reason: "self" });

    // offer to viewer
    const offer = await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );
    expect(offer.status).toBe("pending");
    expect(offer.expiresAt > offer.createdAt).toBe(true);

    // second offer refused
    await expect(
      orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.member),
    ).rejects.toMatchObject({ reason: "pending_exists" });

    // wrong user accepting
    await expect(
      orgService.acceptOwnershipHandover(tenant.actors.member, tenant.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });

    const seenTransfers: unknown[] = [];
    const seenRoleChanges: unknown[] = [];
    const off1 = subscribe("organization.ownership_transferred", (p) => seenTransfers.push(p));
    const off2 = subscribe("member.role_changed", (p) => seenRoleChanges.push(p));

    const org = await orgService.acceptOwnershipHandover(tenant.actors.viewer, tenant.org.id);
    expect(org.ownerId).toBe(tenant.userIds.viewer);
    expect(seenTransfers).toHaveLength(1);
    expect(seenTransfers[0]).toMatchObject({
      fromUserId: tenant.userIds.owner,
      toUserId: tenant.userIds.viewer,
      actorId: tenant.userIds.viewer,
    });
    // viewer promoted to owner, original owner demoted to admin
    expect(seenRoleChanges).toEqual(
      expect.arrayContaining([
        expect.objectContaining({ from: "viewer", to: "owner" }),
        expect.objectContaining({ from: "owner", to: "admin" }),
      ]),
    );
    off1();
    off2();

    const originalOwnerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    expect(originalOwnerMember?.role).toBe("admin");
    const secondOwnerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    expect(secondOwnerMember?.role).toBe("owner"); // untouched, already was owner

    // decline path
    const offer2 = await orgService.initiateOwnershipHandover(
      { userId: tenant.userIds.viewer, orgId: tenant.org.id, role: "owner" },
      tenant.org.id,
      tenant.userIds.member,
    );
    const declined = await orgService.declineOwnershipHandover(tenant.actors.member, tenant.org.id);
    expect(declined.status).toBe("declined");
    expect(declined.resolvedAt).not.toBeNull();
    const pendingAfterDecline = await orgService.getPendingOwnershipHandover(
      tenant.actors.member,
      tenant.org.id,
    );
    expect(pendingAfterDecline).toBeNull();

    // cancel path
    const offer3 = await orgService.initiateOwnershipHandover(
      { userId: tenant.userIds.viewer, orgId: tenant.org.id, role: "owner" },
      tenant.org.id,
      tenant.userIds.member,
    );
    const canceled = await orgService.cancelOwnershipHandover(
      { userId: tenant.userIds.viewer, orgId: tenant.org.id, role: "owner" },
      tenant.org.id,
    );
    expect(canceled.status).toBe("canceled");

    // withdrawing again -> nothing_pending
    await expect(
      orgService.cancelOwnershipHandover(
        { userId: tenant.userIds.viewer, orgId: tenant.org.id, role: "owner" },
        tenant.org.id,
      ),
    ).rejects.toMatchObject({ reason: "nothing_pending" });

    // auto-withdraw when offered member is removed
    const offer4 = await orgService.initiateOwnershipHandover(
      { userId: tenant.userIds.viewer, orgId: tenant.org.id, role: "owner" },
      tenant.org.id,
      tenant.userIds.member,
    );
    const memberRow = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    await memberService.removeMember(
      { userId: tenant.userIds.viewer, orgId: tenant.org.id, role: "owner" },
      { orgId: tenant.org.id, memberId: memberRow!.id },
    );
    const pendingAfterRemoval = await orgService.getPendingOwnershipHandover(
      { userId: tenant.userIds.viewer, orgId: tenant.org.id, role: "owner" },
      tenant.org.id,
    );
    expect(pendingAfterRemoval).toBeNull();

    cleanup();
  });

  it("expiry lapses an offer", async () => {
    cleanup = await useTemporaryDatabase();
    const tenant: Tenant = await createTenant("handover-expiry", "growth");

    const offer = await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.member,
    );

    vi.useFakeTimers();
    vi.setSystemTime(new Date(Date.parse(offer.expiresAt) + 1000));

    await expect(
      orgService.acceptOwnershipHandover(tenant.actors.member, tenant.org.id),
    ).rejects.toMatchObject({ reason: "expired" });

    const pending = await orgService.getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id);
    expect(pending).toBeNull();

    // new offer allowed once lapsed
    const offer2 = await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );
    expect(offer2.status).toBe("pending");

    vi.useRealTimers();
    cleanup();
  });
});
EOF
