1	/**
2	 * Organization creation, settings updates and deletion; seeds the owner membership and the free subscription.
3	 *
4	 * Must call (do not reimplement): assertCan, assertOrgScope, emit, uniqueSlug, assertValidSlug
5	 */
6	import { emit } from "@/lib/event-bus";
7	import { OwnershipHandoverError } from "@/lib/errors";
8	import { assertCan, PermissionDeniedError } from "@/lib/permissions";
9	import { assertValidSlug, uniqueSlug } from "@/lib/slug";
10	import { assertOrgScope } from "@/lib/tenant";
11	import * as memberRepo from "@/server/repositories/member-repository";
12	import * as orgRepo from "@/server/repositories/organization-repository";
13	import * as ownershipHandoverRepo from "@/server/repositories/ownership-handover-repository";
14	import * as projectRepo from "@/server/repositories/project-repository";
15	import * as subscriptionRepo from "@/server/repositories/subscription-repository";
16	import * as usageRepo from "@/server/repositories/usage-repository";
17	import { record } from "./activity-service";
18	import { notify } from "./notification-service";
19	import {
20	  NotFoundError,
21	  actorEnvelope,
22	  envelope,
23	  orgResource,
24	  requireFound,
25	} from "./_support";
26	import { toIsoTimestamp } from "@/types/common";
27	import type {
28	  CreateOrganizationInput,
29	  DeleteOrganizationInput,
30	  UpdateOrganizationInput,
31	} from "@/schemas/organization";
32	import type { OrgId, UserId } from "@/types/common";
33	import type { Actor } from "@/types/member";
34	import type {
35	  Organization,
36	  OrganizationSummary,
37	  OwnershipHandover,
38	} from "@/types/organization";
39	
40	/**
41	 * Creates an organization and everything it cannot exist without: the owner's
42	 * membership row and a subscription. Sign-up and "create another workspace"
43	 * both land here, which is why it takes a bare `ownerId` rather than an
44	 * `Actor` — there is no membership to build one from yet.
45	 */
46	export async function createOrganization(
47	  ownerId: UserId,
48	  input: CreateOrganizationInput,
49	): Promise<Organization> {
50	  assertValidSlug(input.slug);
51	
52	  const taken = await orgRepo.listTakenOrgSlugs(input.slug);
53	  const slug = uniqueSlug(input.slug, taken);
54	
55	  const org = await orgRepo.insertOrg({ ...input, slug }, ownerId);
56	
57	  const owner = await memberRepo.insertMember(org.id, ownerId, "owner", null);
58	  await subscriptionRepo.insertSubscription(org.id, input.plan, "monthly");
59	  await usageRepo.recomputeUsage(org.id);
60	
61	  await emit("member.joined", {
62	    ...envelope(org.id, ownerId),
63	    memberId: owner.id,
64	    userId: ownerId,
65	    role: owner.role,
66	  });
67	
68	  return org;
69	}
70	
71	export async function updateOrganization(
72	  actor: Actor,
73	  input: UpdateOrganizationInput,
74	): Promise<Organization> {
75	  assertOrgScope(actor, input.orgId);
76	  assertCan(actor, "org:update", orgResource(input.orgId));
77	
78	  const updated = await orgRepo.updateOrg(input.orgId, input);
79	
80	  // Settings changes are audited directly: the event bus has no
81	  // `organization.updated` key, and inventing one would widen the contract.
82	  await record(input.orgId, "organization.updated", {
83	    actorId: actor.userId,
84	    subjectKind: "organization",
85	    subjectId: updated.id,
86	    projectId: null,
87	    summary: `${updated.name} settings updated`,
88	  });
89	
90	  return updated;
91	}
92	
93	/**
94	 * Deletion is a soft delete guarded by a typed confirmation, the same shape
95	 * GitHub uses: the caller has to retype the slug.
96	 */
97	export async function deleteOrganization(
98	  actor: Actor,
99	  input: DeleteOrganizationInput,
100	): Promise<Organization> {
101	  assertOrgScope(actor, input.orgId);
102	  assertCan(actor, "org:delete", orgResource(input.orgId));
103	
104	  const org = requireFound(
105	    await orgRepo.findOrgById(input.orgId),
106	    "Organization",
107	    input.orgId,
108	  );
109	
110	  if (org.slug !== input.confirmSlug) {
111	    throw new Error("The confirmation does not match this organization's slug");
112	  }
113	
114	  return orgRepo.archiveOrg(input.orgId);
115	}
116	
117	/** The header/shell payload: the org plus the counters the sidebar shows. */
118	export async function getOrganizationSummary(
119	  actor: Actor,
120	  orgId: OrgId,
121	): Promise<OrganizationSummary> {
122	  assertOrgScope(actor, orgId);
123	  assertCan(actor, "org:read", orgResource(orgId));
124	
125	  const organization = requireFound(
126	    await orgRepo.findOrgById(orgId),
127	    "Organization",
128	    orgId,
129	  );
130	
131	  return {
132	    organization,
133	    usage: await usageRepo.getUsage(orgId),
134	    memberCount: await memberRepo.countActiveMembers(orgId),
135	    projectCount: await projectRepo.countProjects(orgId),
136	  };
137	}
138	
139	/** The org switcher's list; no `Actor` exists until one is chosen. */
140	export async function listOrganizationsForUser(
141	  userId: UserId,
