/**
 * Organization creation, settings updates and deletion; seeds the owner membership and the free subscription.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, uniqueSlug, assertValidSlug
 */
import { emit } from "@/lib/event-bus";
import { OwnershipHandoverError } from "@/lib/errors";
import { assertCan, PermissionDeniedError } from "@/lib/permissions";
import { assertValidSlug, uniqueSlug } from "@/lib/slug";
import { assertOrgScope } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as ownershipHandoverRepo from "@/server/repositories/ownership-handover-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { record } from "./activity-service";
import { notify } from "./notification-service";
import {
  NotFoundError,
  actorEnvelope,
  envelope,
  orgResource,
  requireFound,
} from "./_support";
import { toIsoTimestamp } from "@/types/common";
import type {
  CreateOrganizationInput,
  DeleteOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import type {
  Organization,
  OrganizationSummary,
  OwnershipHandover,
} from "@/types/organization";

/**
 * Creates an organization and everything it cannot exist without: the owner's
 * membership row and a subscription. Sign-up and "create another workspace"
 * both land here, which is why it takes a bare `ownerId` rather than an
 * `Actor` — there is no membership to build one from yet.
 */
export async function createOrganization(
  ownerId: UserId,
  input: CreateOrganizationInput,
): Promise<Organization> {
  assertValidSlug(input.slug);

  const taken = await orgRepo.listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);

  const org = await orgRepo.insertOrg({ ...input, slug }, ownerId);

  const owner = await memberRepo.insertMember(org.id, ownerId, "owner", null);
  await subscriptionRepo.insertSubscription(org.id, input.plan, "monthly");
  await usageRepo.recomputeUsage(org.id);

  await emit("member.joined", {
    ...envelope(org.id, ownerId),
    memberId: owner.id,
    userId: ownerId,
    role: owner.role,
  });

  return org;
}

export async function updateOrganization(
  actor: Actor,
  input: UpdateOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const updated = await orgRepo.updateOrg(input.orgId, input);

  // Settings changes are audited directly: the event bus has no
  // `organization.updated` key, and inventing one would widen the contract.
  await record(input.orgId, "organization.updated", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: updated.id,
    projectId: null,
    summary: `${updated.name} settings updated`,
  });

  return updated;
}

/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  return orgRepo.archiveOrg(input.orgId);
}

/** The header/shell payload: the org plus the counters the sidebar shows. */
export async function getOrganizationSummary(
  actor: Actor,
  orgId: OrgId,
): Promise<OrganizationSummary> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const organization = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );

  return {
    organization,
    usage: await usageRepo.getUsage(orgId),
    memberCount: await memberRepo.countActiveMembers(orgId),
    projectCount: await projectRepo.countProjects(orgId),
  };
}

/** The org switcher's list; no `Actor` exists until one is chosen. */
export async function listOrganizationsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  return orgRepo.listOrgsForUser(userId);
}

export async function resolveOrgBySlug(
  slug: string,
): Promise<Organization | null> {
  return orgRepo.findOrgBySlug(slug);
}

/**
 * Result of looking up the org's one-at-a-time offer. Kept apart from a bare
 * `OwnershipHandover | null` because accept/decline and cancel/initiate each
 * need to tell "nothing was ever offered" apart from "it lapsed" — the two
 * collapse to the same refusal for cancel and initiate, but not for accept
 * and decline.
 */
type HandoverLookup =
  | { readonly kind: "open"; readonly handover: OwnershipHandover }
  | { readonly kind: "expired" }
  | { readonly kind: "none" };

/** Reads the org's pending offer, if any, lazily expiring it past its TTL. */
async function lookupHandover(orgId: OrgId): Promise<HandoverLookup> {
  const handover = await ownershipHandoverRepo.findPendingHandover(orgId);
  if (!handover) return { kind: "none" };

  if (handover.expiresAt <= toIsoTimestamp(new Date())) {
    await ownershipHandoverRepo.markExpired(orgId, handover.id);
    return { kind: "expired" };
  }

  return { kind: "open", handover };
}

/**
 * Only the recorded owner — `organization.ownerId` — may offer or withdraw.
 * Holding the `owner` role is not enough, so this cannot be expressed as a
 * `ROLE_MATRIX` lookup; it still throws the same `PermissionDeniedError`
 * every other authorization failure does.
 */
function assertRecordedOwner(actor: Actor, org: Organization): void {
  if (actor.userId === org.ownerId) return;

  throw new PermissionDeniedError("org:manage_ownership", {
    allowed: false,
    action: "org:manage_ownership",
    resourceKind: "organization",
    reason: "denied_by_role",
  });
}

/**
 * Offers the workspace to another active member. Refused with
 * `OwnershipHandoverError` for a conflicting state (an offer already open,
 * offering to oneself) and `NotFoundError` for an ineligible target.
 */
export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  assertRecordedOwner(actor, org);

  if (toUserId === actor.userId) {
    throw new OwnershipHandoverError("self");
  }

  const target = requireFound(
    await memberRepo.findMember(orgId, toUserId),
    "Member",
    toUserId,
  );
  if (target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const lookup = await lookupHandover(orgId);
  if (lookup.kind === "open") {
    throw new OwnershipHandoverError("pending_exists");
  }

  const handover = await ownershipHandoverRepo.insertHandover(
    orgId,
    actor.userId,
    toUserId,
  );

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "You've been offered ownership of this workspace",
    body: `${actor.userId} offered to hand you ownership of this workspace`,
    href: "/settings/members",
    actorId: actor.userId,
  });

  return handover;
}

/**
 * Accepts the workspace offered to the actor. The accepting member ends up
 * with the `owner` role and as the recorded owner; the previous owner steps
 * down to `admin` if they still held `owner` at that moment. The promotion
 * always runs before the demotion so the workspace never has zero owners.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);

  const lookup = await lookupHandover(orgId);
  if (lookup.kind === "none") throw new OwnershipHandoverError("nothing_pending");
  if (lookup.kind === "expired") throw new OwnershipHandoverError("expired");

  const { handover } = lookup;
  if (handover.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  const toMember = requireFound(
    await memberRepo.findMember(orgId, handover.toUserId),
    "Member",
    handover.toUserId,
  );
  const fromMember = await memberRepo.findMember(orgId, handover.fromUserId);

  if (toMember.role !== "owner") {
    const promoted = await memberRepo.updateMemberRole(orgId, toMember.id, "owner");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: promoted.id,
      from: toMember.role,
      to: promoted.role,
    });
  }

  if (fromMember && fromMember.role === "owner") {
    const demoted = await memberRepo.updateMemberRole(orgId, fromMember.id, "admin");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: demoted.id,
      from: fromMember.role,
      to: demoted.role,
    });
  }

  const org = await orgRepo.setOwner(orgId, handover.toUserId);

  await ownershipHandoverRepo.resolveHandover(orgId, handover.id, "accepted");

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: handover.fromUserId,
    toUserId: handover.toUserId,
  });

  return org;
}

/** Declines the offer made to the actor; the owner may offer again afterward. */
export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const lookup = await lookupHandover(orgId);
  if (lookup.kind === "none") throw new OwnershipHandoverError("nothing_pending");
  if (lookup.kind === "expired") throw new OwnershipHandoverError("expired");

  const { handover } = lookup;
  if (handover.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  return ownershipHandoverRepo.resolveHandover(orgId, handover.id, "declined");
}

/** Withdraws the offer the recorded owner made, while it is still open. */
export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  assertRecordedOwner(actor, org);

  const lookup = await lookupHandover(orgId);
  if (lookup.kind !== "open") {
    throw new OwnershipHandoverError("nothing_pending");
  }

  return ownershipHandoverRepo.resolveHandover(orgId, lookup.handover.id, "canceled");
}

/** The workspace's open offer, or `null` — visible to any member. */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);

  const lookup = await lookupHandover(orgId);
  return lookup.kind === "open" ? lookup.handover : null;
}
